var i=`0291-cicvara`;var r=`world-0291`;var n=`ME`;var a=`southern-europe`;var s=4;var o=17;var l={en:`Cicvara`,ua:`Цицвара`};var u={en:`A traditional Montenegro dish made with whole cow milk, cornmeal, farmer cheese. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Чорногорія. Основні інгредієнти: цільне коров'яче молоко, кукурудзяна крупа дрібного помелу, домашній кисломолочний сир. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`whole-cow-milk`,750,`ml`],[`water`,250,`ml`],[`cornmeal`,250,`g`],[`table-salt`,4,`g`]]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:5,i:[[`unsalted-butter`,90,`g`],[`farmer-cheese`,250,`g`]]}];var g={slug:i,id:r,country:`ME`,region:a,servings:4,minutes:17,title:l,text:u,steps:m};export{n as country,g as default,r as id,o as minutes,a as region,s as servings,i as slug,m as steps,u as text,l as title};